/**
 * PANODROME — Stage 2.1 · Architectural Material Palette + Tap Switcher
 * ============================================================================
 * (Owner order 2026-11-03 — "تغییر زنده متریال با تپ"):
 * All 11 true-3D rooms share ONE small palette of seamless PBR textures
 * (assets/true3d/mats/palette.json, generated by skills/build_all_3d_rooms.py).
 * GLB meshes reference materials by NAME ("x_<paletteKey>#<kind>") and this
 * module assembles real MeshStandardMaterials from the palette — so the
 * whole suite costs one ~1 MB download and switching is INSTANT.
 *
 * Tap the floor / a wall / a furniture piece in Walk or Dollhouse mode →
 * that surface kind cycles through the room's curated material list
 * (rooms_db.json "mats") with a live update + a naming toast.
 */
import * as THREE from "three";
import { i18n } from "./i18n.js";

const PALETTE_URL = "assets/true3d/mats/palette.json";
const TEX_ROOT = "assets/true3d/";

let manifest = null;
const matCache = new Map();      // "<key>#<kind>" -> MeshStandardMaterial
const texLoader = new THREE.TextureLoader();
const texCache = new Map();      // key -> THREE.Texture

async function ensureManifest() {
  if (manifest) return manifest;
  const res = await fetch(PALETTE_URL);
  manifest = await res.json();
  return manifest;
}

function textureFor(key, entry) {
  if (texCache.has(key)) return texCache.get(key);
  const tex = texLoader.load(TEX_ROOT + entry.map);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;   // UV tiling is baked per-mesh
  tex.anisotropy = 4;
  texCache.set(key, tex);
  return tex;
}

/** Build (and cache) the MeshStandardMaterial for a palette key + surface kind. */
export async function materialFor(key, kind = "furn") {
  await ensureManifest();
  const ck = key + "#" + kind;
  if (matCache.has(ck)) return matCache.get(ck);
  const entry = manifest[key] || { color: [0.75, 0.75, 0.75], rough: 0.8, metal: 0.0 };
  const params = {
    name: "x_" + ck,
    roughness: entry.rough ?? 0.8,
    metalness: entry.metal ?? 0.0,
  };
  if (entry.map) params.map = textureFor(key, entry);
  else if (entry.color) params.color = new THREE.Color(...entry.color);
  if (entry.emissive) {
    params.emissive = new THREE.Color(...entry.emissive);
    params.emissiveIntensity = entry.emissiveIntensity ?? 1.2;
  }
  if (entry.alpha != null) {
    params.transparent = true;
    params.opacity = entry.alpha;
  }
  // The .glb files carry NO normal attributes (compact palette geometry) —
  // GLTFLoader would set flatShading for such primitives; we assemble the
  // materials ourselves, so do the same (faceted normals from derivatives,
  // which is exact for our box-built architecture).
  params.flatShading = true;
  const m = new THREE.MeshStandardMaterial(params);
  m.envMapIntensity = 0.4;               // pano IBL stays subtle
  matCache.set(ck, m);
  return m;
}

/** Palette display name (any language), for the switch toast. */
export function paletteName(key) {
  const e = (manifest || {})[key];
  return e && e.name ? (e.name[i18n.lang] || e.name.en) : key;
}

export function paletteKeys() {
  return manifest ? Object.keys(manifest) : [];
}

/* --------------------------------------------------- room surface registry */

/**
 * Walk a GLTF root, resolve every "x_<key>#<kind>" material from the palette
 * and index the meshes by surface kind (floor / wall / furn) for the
 * tap-to-cycle switcher.
 */
export class SurfaceRegistry {
  constructor() {
    this.byKind = { floor: [], wall: [], furn: [] };
    this.original = {};          // kind -> original palette key
    this.current = {};           // kind -> current palette key
  }

  static kindOf(mesh) {
    const n = mesh.name || "";
    if (n.startsWith("floor")) return "floor";
    if (n.startsWith("wall")) return "wall";
    if (n.startsWith("ceiling") || n.startsWith("roof")) return null;  // not switchable
    return "furn";
  }

  async bind(root) {
    const jobs = [];
    root.traverse((o) => {
      if (!o.isMesh) return;
      const matName = (Array.isArray(o.material) ? o.material[0] : o.material)?.name || "";
      if (!matName.startsWith("x_")) return;
      const key = matName.slice(2).split("#")[0];
      const kind = SurfaceRegistry.kindOf(o);
      const bindKind = kind || "furn";
      jobs.push(materialFor(key, bindKind).then((m) => {
        if (Array.isArray(o.material)) o.material[0] = m;
        else o.material = m;
        o.userData.paletteKey = key;
      }));
      if (kind) {
        this.byKind[kind].push(o);
        if (!(kind in this.original)) {
          this.original[kind] = key;
          this.current[kind] = key;
        }
      }
    });
    await Promise.all(jobs);
    return this;
  }

  /** Cycle one surface kind to the palette key at index +1 (or given key). */
  async cycle(kind, roomMats) {
    const list = (roomMats && roomMats[kind]) || [];
    if (!list.length || !this.byKind[kind].length) return null;
    const cur = this.current[kind];
    let idx = list.indexOf(cur);
    idx = (idx + 1) % list.length;
    const key = list[idx];
    this.current[kind] = key;
    await this.apply(kind, key);
    return key;
  }

  /** Jump to a specific palette key on one surface kind. */
  async apply(kind, key) {
    const m = await materialFor(key, kind);
    for (const mesh of this.byKind[kind]) {
      if (Array.isArray(mesh.material)) mesh.material[0] = m;
      else mesh.material = m;
      mesh.userData.paletteKey = key;
    }
  }

  state() {
    const out = {};
    for (const k of Object.keys(this.byKind)) {
      out[k] = {
        key: this.current[k] || null,
        original: this.original[k] || null,
        meshes: this.byKind[k].length,
      };
    }
    return out;
  }
}
